from telemetry_stream import prepare_metric_packet, publish_stream_packet

def test_nominal_metric_packet():
    raw = {"val": 1.0}
    pkt = prepare_metric_packet(raw, 200)
    assert isinstance(pkt, dict)
    assert publish_stream_packet(raw, 200) == pkt

def test_service_execution():
    raw = {"val": 1.0}
    pkt = prepare_metric_packet(raw, 200)
    assert pkt is not None
    assert pkt.get("_v") == 2
    assert pkt.get("_src") == "telemetry"
    assert pkt.get("payload") == raw
